(2702496, 375835, 5034, '<td valign="top">Awesome photo and I hate to have to do this, it has the tiniest bit of motion blur in the wings - I know the go 50 beats per second but the challenge says no motion trails.  7</td>', 'Awesome photo and I hate to have to do this, it has the tiniest bit of motion blur in the wings - I know the go 50 beats per second but the challenge says no motion trails.  7', '2006-08-07 11:35:04.000000', NULL, 1),
(2702514, 372827, 31403, '<td valign="top">crop right down to the action - you only have to submit 640 pixels - make them all count!</td>', 'crop right down to the action - you only have to submit 640 pixels - make them all count!', '2006-08-07 11:45:32.000000', NULL, 1),
