(2713897, 374375, 56725, '<td valign="top">nicely done!</td>', 'nicely done!', '2006-08-10 08:12:30.000000', NULL, 1),
(2713898, 375655, 56725, '<td valign="top">such vibrant colors!</td>', 'such vibrant colors!', '2006-08-10 08:13:16.000000', NULL, 1),
(2713986, 375572, 34938, '<td valign="top">very good! a good vantage point</td>', 'very good! a good vantage point', '2006-08-10 09:00:18.000000', NULL, 1),
(2713990, 375594, 34938, '<td valign="top">perhaps too tight in the crop cause it would be better if you could see feet and more of the ball</td>', 'perhaps too tight in the crop cause it would be better if you could see feet and more of the ball', '2006-08-10 09:01:20.000000', NULL, 1),
(2713994, 375686, 34938, '<td valign="top">lovely in b and w and I like the black border as well...would have liked just a tad more space at the bottom to make room for the feet...very nice</td>', 'lovely in b and w and I like the black border as well...would have liked just a tad more space at the bottom to make room for the feet...very nice', '2006-08-10 09:02:50.000000', NULL, 1),
(2713997, 375787, 34938, '<td valign="top">that''s good, but quite oversharpened...a great expression and nice light and colour though</td>', 'that''s good, but quite oversharpened...a great expression and nice light and colour though', '2006-08-10 09:03:38.000000', NULL, 1),
(2714000, 375573, 34938, '<td valign="top">Oh wow, awesome light and a great action shot....I would have cloned out the stray grass, but that''s just a personal thing...very good shot</td>', 'Oh wow, awesome light and a great action shot....I would have cloned out the stray grass, but that''s just a personal thing...very good shot', '2006-08-10 09:04:33.000000', NULL, 1),
(2714002, 375791, 34938, '<td valign="top">great, fun expression...just lacks a bit of sharpness, but I like the shot, well done</td>', 'great, fun expression...just lacks a bit of sharpness, but I like the shot, well done', '2006-08-10 09:05:46.000000', NULL, 1),
(2714004, 375746, 34938, '<td valign="top">spooooooooky!</td>', 'spooooooooky!', '2006-08-10 09:06:06.000000', NULL, 1),
