(2714009, 375771, 34938, '<td valign="top">awesome...great as a selective desaturation and effective...well done and good luck</td>', 'awesome...great as a selective desaturation and effective...well done and good luck', '2006-08-10 09:07:55.000000', NULL, 1),
(2714016, 375514, 34938, '<td valign="top">the timing on this is perfect...like the blue and the blue frame...great lighting, well done</td>', 'the timing on this is perfect...like the blue and the blue frame...great lighting, well done', '2006-08-10 09:10:26.000000', NULL, 1),
