INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2714022, 375707, 29069, '<td valign="top">wow. love this. can see compression artifacts on the background, possibly due to the size limitation for entries but otherwise a great, weightless photo.</td>', 'wow. love this. can see compression artifacts on the background, possibly due to the size limitation for entries but otherwise a great, weightless photo.', '2006-08-10 09:12:03.000000', NULL, 1),
(2714026, 374058, 34938, '<td valign="top">great blue...nice shot and great timing</td>', 'great blue...nice shot and great timing', '2006-08-10 09:12:43.000000', NULL, 1),
(2714027, 374600, 34938, '<td valign="top">great title for this</td>', 'great title for this', '2006-08-10 09:12:56.000000', NULL, 1),
(2714028, 373870, 34938, '<td valign="top">great shot, but perhaps way overdone on the neat image...colours and comp are fantastic 7</td>', 'great shot, but perhaps way overdone on the neat image...colours and comp are fantastic 7', '2006-08-10 09:14:29.000000', NULL, 1),
(2714031, 375722, 34938, '<td valign="top">wow! that''s awesome...</td>', 'wow! that''s awesome...', '2006-08-10 09:15:11.000000', NULL, 1),
(2714088, 375853, 37320, '<td valign="top">Great shot, I love the background, my only suggestion would be to dress up your model more interestingly.  Maybe instead of a batman shirt, a batman outfit for example.</td>', 'Great shot, I love the background, my only suggestion would be to dress up your model more interestingly.  Maybe instead of a batman shirt, a batman outfit for example.', '2006-08-10 09:40:13.000000', NULL, 1),
(2714135, 375614, 23394, '<td valign="top">yes, you caught a moment, and the expression is priceless.  although my initial reaction was tepid, i do think this is an above average image.</td>', 'yes, you caught a moment, and the expression is priceless.  although my initial reaction was tepid, i do think this is an above average image.', '2006-08-10 09:58:54.000000', NULL, 1),
(2714139, 374986, 23394, '<td valign="top">nice idea, but a little on the snap-shotty side.  while this is a bit too busy to really get a feel for stopping the motion, the idea does look like it would have some potential, if you could have isolated one single subject getting wailed on.</td>', 'nice idea, but a little on the snap-shotty side.  while this is a bit too busy to really get a feel for stopping the motion, the idea does look like it would have some potential, if you could have isolated one single subject getting wailed on.', '2006-08-10 10:00:40.000000', NULL, 1),
(2714140, 375911, 23394, '<td valign="top">ok, you''ve stopped motion, but you haven''t caught my attention.  maybe if shot from a different perspective?  i''m having a hard time putting my finger on what it is, but there''s something about this image that just doesn''t grab me.</td>', 'ok, you''ve stopped motion, but you haven''t caught my attention.  maybe if shot from a different perspective?  i''m having a hard time putting my finger on what it is, but there''s something about this image that just doesn''t grab me.', '2006-08-10 10:00:44.000000', NULL, 1),
(2714145, 374700, 23394, '<td valign="top">i''m sure this is legal, but the post-processing makes it look a little weird.  maybe it''s just the lighting.  nice idea, but it doesn''t really grab me.</td>', 'i''m sure this is legal, but the post-processing makes it look a little weird.  maybe it''s just the lighting.  nice idea, but it doesn''t really grab me.', '2006-08-10 10:01:56.000000', NULL, 1),
(2714150, 375710, 23394, '<td valign="top">ok, you''ve stopped some motion, and i know this took some work.  i just wish you had gone a little more overboard and 1) made MORE stuff be flying out, and 2) shot a bit tighter--as is, there''s so much clutter that the flying noodles are somewhat lost.</td>', 'ok, you''ve stopped some motion, and i know this took some work.  i just wish you had gone a little more overboard and 1) made MORE stuff be flying out, and 2) shot a bit tighter--as is, there''s so much clutter that the flying noodles are somewhat lost.', '2006-08-10 10:03:27.000000', NULL, 1),
(2714154, 375274, 23394, '<td valign="top">nice idea, but needs work.  the image is a bit muted, indicating that it could use some more post-processing.  also, it could have been submitted quite a bit larger.</td>', 'nice idea, but needs work.  the image is a bit muted, indicating that it could use some more post-processing.  also, it could have been submitted quite a bit larger.', '2006-08-10 10:04:40.000000', NULL, 1),
(2714157, 375366, 23394, '<td valign="top">you''ve stopped the water, yes, but the overall image is just a bit too dark.  i looks like a scene that has potential, but, as it''s rendered here, it doesn''t really do much for me.</td>', 'you''ve stopped the water, yes, but the overall image is just a bit too dark.  i looks like a scene that has potential, but, as it''s rendered here, it doesn''t really do much for me.', '2006-08-10 10:05:56.000000', NULL, 1),
(2714159, 375474, 23394, '<td valign="top">nice idea, but needs work technically and compositionally.</td>', 'nice idea, but needs work technically and compositionally.', '2006-08-10 10:06:28.000000', NULL, 1),
(2714175, 375819, 23394, '<td valign="top">too soft, and not enough apparent sense of motion.  maybe if you had shot this vertically, it would be stronger.</td>', 'too soft, and not enough apparent sense of motion.  maybe if you had shot this vertically, it would be stronger.', '2006-08-10 10:11:20.000000', NULL, 1),
(2714230, 375911, 42495, '<td valign="top">Simple shot and captures the subject well.  I like all the little detail, like around her hand in the sand.</td>', 'Simple shot and captures the subject well.  I like all the little detail, like around her hand in the sand.', '2006-08-10 10:33:16.000000', NULL, 1),
(2714231, 375881, 42495, '<td valign="top">Good composition and you really caught the motion well.  I like the PP.</td>', 'Good composition and you really caught the motion well.  I like the PP.', '2006-08-10 10:34:30.000000', NULL, 1),
(2714234, 375891, 42495, '<td valign="top">Not a ton of motion here, but I like colors and reflection on the water.  Body of the bird looks just a tad bit dark.</td>', 'Not a ton of motion here, but I like colors and reflection on the water.  Body of the bird looks just a tad bit dark.', '2006-08-10 10:35:39.000000', NULL, 1),
(2714249, 374493, 42495, '<td valign="top">I like the angle and how you captured the moment.  The kids watching in the background add to the shot.  Overall, well done.  What would make it even better would be to lose the orange cone, and the horizon looks a bit tilted down towards the left.</td>', 'I like the angle and how you captured the moment.  The kids watching in the background add to the shot.  Overall, well done.  What would make it even better would be to lose the orange cone, and the horizon looks a bit tilted down towards the left.', '2006-08-10 10:40:30.000000', NULL, 1),
(2714255, 373501, 42495, '<td valign="top">From the angle it''s a bit hard to tell if it''s in motion, but I''ll assume it was.  Nice, clear picture, and the yellow/purple flower combination works.</td>', 'From the angle it''s a bit hard to tell if it''s in motion, but I''ll assume it was.  Nice, clear picture, and the yellow/purple flower combination works.', '2006-08-10 10:41:55.000000', NULL, 1),
(2714293, 375591, 45375, '<td valign="top">Great shot! I love the scale between the jumper and rock</td>', 'Great shot! I love the scale between the jumper and rock', '2006-08-10 10:58:06.000000', NULL, 1),
(2714297, 375507, 45375, '<td valign="top">wow...i love how you can see individual feathers</td>', 'wow...i love how you can see individual feathers', '2006-08-10 10:59:20.000000', NULL, 1),
(2714367, 375827, 31403, '<td valign="top">if the leaper were the only person in this shot it would 10 times better IMO - and if he was in street clothes stronger still - almost pink floyd-esc.<br/> <br/>Still a great capture - my twelve year old who came in loves it too! 7</td>', 'if the leaper were the only person in this shot it would 10 times better IMO - and if he was in street clothes stronger still - almost pink floyd-esc. Still a great capture - my twelve year old who came in loves it too! 7', '2006-08-10 11:36:07.000000', NULL, 1),
(2714368, 375686, 24913, '<td valign="top">Beutiful! Love the crop. (well, and the dog of course)</td>', 'Beutiful! Love the crop. (well, and the dog of course)', '2006-08-10 11:36:43.000000', NULL, 1),
(2714380, 375902, 31403, '<td valign="top">brighten those whites and you''ve got a amazing shot!  Ok - this is a great shot but I wish the whites were really white!  How''s that?  I''ll give you a 7 - full tonal range would garner an even higher score.  This is great photo work - sharpness and composition is right on.</td>', 'brighten those whites and you''ve got a amazing shot!  Ok - this is a great shot but I wish the whites were really white!  How''s that?  I''ll give you a 7 - full tonal range would garner an even higher score.  This is great photo work - sharpness and composition is right on.', '2006-08-10 11:40:00.000000', NULL, 1),
(2714384, 375260, 31403, '<td valign="top">very clever execution - I think a "bar" kind of background might be better - well let''s just say the large expanse of black is really over powering in the shot that''s here, and I wish there was something else back there.<br/> <br/>7</td>', 'very clever execution - I think a "bar" kind of background might be better - well let''s just say the large expanse of black is really over powering in the shot that''s here, and I wish there was something else back there. 7', '2006-08-10 11:41:47.000000', NULL, 1),
(2714397, 375209, 31403, '<td valign="top">mine has more air than yours, but yours is sharper!  (can you guess which one mine is?  ;-)  )<br/> <br/>These are great places to shoot and I hope to spend more time at our local park.<br/> <br/>Love the shadow behind him defining and giving contrast tot he board and shoes.  Nice work.</td>', 'mine has more air than yours, but yours is sharper!  (can you guess which one mine is?  ;-)  ) These are great places to shoot and I hope to spend more time at our local park. Love the shadow behind him defining and giving contrast tot he board and shoes.  Nice work.', '2006-08-10 11:45:12.000000', NULL, 1),
(2714405, 374999, 31403, '<td valign="top">this is a fabulous image in the wrong challenge - sorry<br/> <br/>The challenge said "no blurs" and I''ll bet I''m not the first to comment on it.<br/> <br/>Is that Larry Miller''s new track in Utah?  The background looks like Utah to me.<br/> <br/>Excellent work though - I know how tough these are to shoot - you''re good at it!</td>', 'this is a fabulous image in the wrong challenge - sorry The challenge said "no blurs" and I''ll bet I''m not the first to comment on it. Is that Larry Miller''s new track in Utah?  The background looks like Utah to me. Excellent work though - I know how tough these are to shoot - you''re good at it!', '2006-08-10 11:47:14.000000', NULL, 1),
(2714410, 375791, 31403, '<td valign="top">Love everything about this but the floor.  Maybe carpet with a couch like she''s watchting a movie?  Could be that you watch movies on tile floors where you are though... hmmm.<br/> <br/>Love the pattern of the popcorn - her hands are shiny, making me think you had to take a lot of photos to get this?  Cute expression on her face too.  Nice work, I appreciate you working hard for your entry.</td>', 'Love everything about this but the floor.  Maybe carpet with a couch like she''s watchting a movie?  Could be that you watch movies on tile floors where you are though... hmmm. Love the pattern of the popcorn - her hands are shiny, making me think you had to take a lot of photos to get this?  Cute expression on her face too.  Nice work, I appreciate you working hard for your entry.', '2006-08-10 11:49:35.000000', NULL, 1),
(2714419, 375809, 31403, '<td valign="top">My 12 year old is standing here and his reaction was "how did they get that fish to do that?"<br/> <br/>My reaction too!  Nice work on baffling everyone at that Havens house!<br/> <br/>Love this.  My monitor shows a little line around the right side of the bowl where you missed dodging - hope you left comments on how you did this.  Would love to try it myself one of these years.<br/> <br/>8</td>', 'My 12 year old is standing here and his reaction was "how did they get that fish to do that?" My reaction too!  Nice work on baffling everyone at that Havens house! Love this.  My monitor shows a little line around the right side of the bowl where you missed dodging - hope you left comments on how you did this.  Would love to try it myself one of these years. 8', '2006-08-10 11:51:37.000000', NULL, 1),
(2714426, 375778, 31403, '<td valign="top">those darn bees are always flying over the most unfortunate backgrounds!  This is a great capture, you must have been shooting REALLY fast to freeze that wing.  But the background is so messy!.  Maybe if you would have cropped right down so the bee is all the way to the right of the frame and that slanting purple to the left?  Don''t know what resolution your working with of course, but for the challenges I try to just think screen resolution and crop that baby down!<br/> <br/>Nice work though, these are hard to get - in fact I''ve stopped trying.  ;-)</td>', 'those darn bees are always flying over the most unfortunate backgrounds!  This is a great capture, you must have been shooting REALLY fast to freeze that wing.  But the background is so messy!.  Maybe if you would have cropped right down so the bee is all the way to the right of the frame and that slanting purple to the left?  Don''t know what resolution your working with of course, but for the challenges I try to just think screen resolution and crop that baby down! Nice work though, these are hard to get - in fact I''ve stopped trying.  ;-)', '2006-08-10 11:54:41.000000', NULL, 1),
(2714440, 375885, 31403, '<td valign="top">the tu-tu and boots are a most captivating combination - I want to love this but the purple is so over-poweringly saturated it kind of wrecks it for me.<br/> <br/>Love the definition in the arms - and that boot!</td>', 'the tu-tu and boots are a most captivating combination - I want to love this but the purple is so over-poweringly saturated it kind of wrecks it for me. Love the definition in the arms - and that boot!', '2006-08-10 11:57:41.000000', NULL, 1),
(2714443, 375881, 31403, '<td valign="top">I can scarcely imagine how hard this is to get - I thought you should know I recognize your skill in getting this!  ;-)  I don''t think the sepia is doing you any favors in this shot though.</td>', 'I can scarcely imagine how hard this is to get - I thought you should know I recognize your skill in getting this!  ;-)  I don''t think the sepia is doing you any favors in this shot though.', '2006-08-10 11:59:04.000000', NULL, 1),
(2714455, 375422, 31403, '<td valign="top">the kid in white and that side of the photo aren''t contributing and thing, and serve to dilute the power of the image you did capture - IMO.  Love your angle - gotta appreciate a photog who''s willing to get down on the ground for their shot!<br/> <br/>The kid in blue seems to be the one in focus, and your main guy a little soft - darn autofocus picking whatever the heck it wants!<br/> <br/>Great sense of timing though, and I love the lighting.  Nice work!</td>', 'the kid in white and that side of the photo aren''t contributing and thing, and serve to dilute the power of the image you did capture - IMO.  Love your angle - gotta appreciate a photog who''s willing to get down on the ground for their shot! The kid in blue seems to be the one in focus, and your main guy a little soft - darn autofocus picking whatever the heck it wants! Great sense of timing though, and I love the lighting.  Nice work!', '2006-08-10 12:01:42.000000', NULL, 1),
