(2717351, 375874, 23394, '<td valign="top">nice shot.  it could stand to be a bit sharper, and framed a bit tighter, though.</td>', 'nice shot.  it could stand to be a bit sharper, and framed a bit tighter, though.', '2006-08-11 11:04:40.000000', NULL, 1),
