(2718041, 375902, 23394, '<td valign="top">as much as i like this, there''s something about it that seems off to me.  it just seems flat when i would expect it to pop.  the lines and textures are great.</td>', 'as much as i like this, there''s something about it that seems off to me.  it just seems flat when i would expect it to pop.  the lines and textures are great.', '2006-08-11 14:57:26.000000', NULL, 1),
(2718048, 374344, 23394, '<td valign="top">this is a tough shot to pull off.  it will be interesting to see how others react to it.  i kinda like it, but am not too crazy about the shadows and the desatting.</td>', 'this is a tough shot to pull off.  it will be interesting to see how others react to it.  i kinda like it, but am not too crazy about the shadows and the desatting.', '2006-08-11 14:59:28.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2718051, 375504, 23394, '<td valign="top">i know what you''re after, but don''t think you quite go there.  that bee is just not sharp enough.  i know this is a tough shot, hopefully the voters won''t be.</td>', 'i know what you''re after, but don''t think you quite go there.  that bee is just not sharp enough.  i know this is a tough shot, hopefully the voters won''t be.', '2006-08-11 15:00:28.000000', NULL, 1),
(2718052, 375324, 23394, '<td valign="top">killer shot!  looks like something i''d like to try to shoot ;-)</td>', 'killer shot!  looks like something i''d like to try to shoot ;-)', '2006-08-11 15:00:52.000000', NULL, 1),
(2718056, 375592, 23394, '<td valign="top">yes, you''ve stopped the motion of the water, but to what purpose?  to meet the challenge.  ok, you''ve done that, but does that really add anything aesthetically to your composition?  as is, it is an eye-level documentation of a statue at a fountain--there''s not much to really make me want to stay with it.</td>', 'yes, you''ve stopped the motion of the water, but to what purpose?  to meet the challenge.  ok, you''ve done that, but does that really add anything aesthetically to your composition?  as is, it is an eye-level documentation of a statue at a fountain--there''s not much to really make me want to stay with it.', '2006-08-11 15:02:41.000000', NULL, 1),
(2718059, 374084, 23394, '<td valign="top">good job stopping the motion; just wish it had been a bit sharper.</td>', 'good job stopping the motion; just wish it had been a bit sharper.', '2006-08-11 15:03:12.000000', NULL, 1),
(2718062, 375829, 23394, '<td valign="top">that''s a cool shot.  if you had framed tighter on your subject, it would have been even more dynamic.</td>', 'that''s a cool shot.  if you had framed tighter on your subject, it would have been even more dynamic.', '2006-08-11 15:05:05.000000', NULL, 1),
(2718064, 375835, 40430, '<td valign="top">nice shot, and detail.</td>', 'nice shot, and detail.', '2006-08-11 15:05:14.000000', NULL, 1),
(2718067, 375791, 40430, '<td valign="top">how m any tires to get this one ? nice job.</td>', 'how m any tires to get this one ? nice job.', '2006-08-11 15:06:30.000000', NULL, 1),
(2718068, 375612, 30049, '<td valign="top">Well, looks like you stopped the motion as the legs aren''t touching and the wings aren''t moving.  ;^)  Lighting looks a bit hot and the fly isn''t sharply focused...looks like some heavy sharpening was applied.  Hard to really tell for sure on this work monitor as it''s not calibrated...  The red glow on the eye is kind of cool.  ;^)  Good luck in the challenge.</td>', 'Well, looks like you stopped the motion as the legs aren''t touching and the wings aren''t moving.  ;^)  Lighting looks a bit hot and the fly isn''t sharply focused...looks like some heavy sharpening was applied.  Hard to really tell for sure on this work monitor as it''s not calibrated...  The red glow on the eye is kind of cool.  ;^)  Good luck in the challenge.', '2006-08-11 15:06:35.000000', NULL, 1),
(2718069, 375722, 23394, '<td valign="top">i could almost accept this shot, except for all the reflections that are screaming ''dining room''...and we all know there''s only one person on this site who would even consider firing a loaded gun in his dining room...<br/> <br/>all the same, nice take on the challenge, good luck!</td>', 'i could almost accept this shot, except for all the reflections that are screaming ''dining room''...and we all know there''s only one person on this site who would even consider firing a loaded gun in his dining room... all the same, nice take on the challenge, good luck!', '2006-08-11 15:06:53.000000', NULL, 1),
(2718071, 374058, 23394, '<td valign="top">nice idea, nice colors.  wish the front edge of the glass was razor sharp, though.  also, this being advanced editing, you could have cleaned up those spots on the side of the glass.</td>', 'nice idea, nice colors.  wish the front edge of the glass was razor sharp, though.  also, this being advanced editing, you could have cleaned up those spots on the side of the glass.', '2006-08-11 15:07:56.000000', NULL, 1),
(2718073, 375791, 23394, '<td valign="top">great idea, just with the popcorn wasn''t blown out.</td>', 'great idea, just with the popcorn wasn''t blown out.', '2006-08-11 15:08:29.000000', NULL, 1),
(2718074, 375816, 30049, '<td valign="top">Nice concept.  Still getting a little blur around the ball which is going to probably take some hits in your score as the challenge called for no motion trails, etc...  Have some noise going on in here also, especially evident in the sky area.  Cool capture nonetheless.  ;^)  Good luck in the challenge.</td>', 'Nice concept.  Still getting a little blur around the ball which is going to probably take some hits in your score as the challenge called for no motion trails, etc...  Have some noise going on in here also, especially evident in the sky area.  Cool capture nonetheless.  ;^)  Good luck in the challenge.', '2006-08-11 15:08:36.000000', NULL, 1),
(2718077, 375689, 23394, '<td valign="top">interesting shot in that i can''t tell what is going on...</td>', 'interesting shot in that i can''t tell what is going on...', '2006-08-11 15:09:13.000000', NULL, 1),
(2718080, 374975, 23394, '<td valign="top">nice take on the cliche.  love the colors, great action on the splash.</td>', 'nice take on the cliche.  love the colors, great action on the splash.', '2006-08-11 15:09:57.000000', NULL, 1),
(2718081, 375881, 23394, '<td valign="top">excellent shot.  one of the best.</td>', 'excellent shot.  one of the best.', '2006-08-11 15:10:15.000000', NULL, 1),
(2718082, 374229, 30049, '<td valign="top">Is she bashful?  ;^)  Interesting composition you have here.  The ratio looks like a panoramic image.  Good job on bringing out the colors - her dress and shoes especially jump out.  Wish you luck in the challenge.</td>', 'Is she bashful?  ;^)  Interesting composition you have here.  The ratio looks like a panoramic image.  Good job on bringing out the colors - her dress and shoes especially jump out.  Wish you luck in the challenge.', '2006-08-11 15:10:47.000000', NULL, 1),
(2718084, 375358, 23394, '<td valign="top">great idea.  would have been even better without the fence, and without his arm being cropped off.  you were on the right track, just think you stopped too soon.</td>', 'great idea.  would have been even better without the fence, and without his arm being cropped off.  you were on the right track, just think you stopped too soon.', '2006-08-11 15:11:26.000000', NULL, 1),
(2718087, 374870, 30049, '<td valign="top">Very good control on the lighting and exposure.  Nice catch on the milk.  Well composed.  Fun to look at.  Should do well with this one.  Good luck.</td>', 'Very good control on the lighting and exposure.  Nice catch on the milk.  Well composed.  Fun to look at.  Should do well with this one.  Good luck.', '2006-08-11 15:12:06.000000', NULL, 1),
(2718090, 375688, 23394, '<td valign="top">what a tough shot to try to pull off.  i haven''t done one, yet, and when i do, it probably won''t be for a challenge--it looks like too much work!  good luck.</td>', 'what a tough shot to try to pull off.  i haven''t done one, yet, and when i do, it probably won''t be for a challenge--it looks like too much work!  good luck.', '2006-08-11 15:13:08.000000', NULL, 1),
(2718095, 375420, 23394, '<td valign="top">i get the idea, and can see some stopped motion, but am not getting a real feel for the image.  it''s just a bit too busy, and the coloring doesn''t really make it pop.</td>', 'i get the idea, and can see some stopped motion, but am not getting a real feel for the image.  it''s just a bit too busy, and the coloring doesn''t really make it pop.', '2006-08-11 15:14:15.000000', NULL, 1),
(2718098, 375568, 23394, '<td valign="top">nice shot.  very clean, sharp, and nice colors.  interesting vignetting, as well.</td>', 'nice shot.  very clean, sharp, and nice colors.  interesting vignetting, as well.', '2006-08-11 15:15:26.000000', NULL, 1),
(2718100, 375755, 30049, '<td valign="top">Another wet kid.  ;^)  Sorry...I''ve been trying to comment on all of the entries in this challenge and I''ve seen a LOT of water at this point.  You''ve done a decent job of freezing (stopping motion) the water splash.  Something about the boy looks funny.  Maybe it''s just the smooth water, but to me it looks like a heavy dose of NI was applied (the hair is the giveaway to me, although I certainly could be wrong).  His face being in shadow is going to take away some from scoring potential also.  Best of luck to you in the challenge.</td>', 'Another wet kid.  ;^)  Sorry...I''ve been trying to comment on all of the entries in this challenge and I''ve seen a LOT of water at this point.  You''ve done a decent job of freezing (stopping motion) the water splash.  Something about the boy looks funny.  Maybe it''s just the smooth water, but to me it looks like a heavy dose of NI was applied (the hair is the giveaway to me, although I certainly could be wrong).  His face being in shadow is going to take away some from scoring potential also.  Best of luck to you in the challenge.', '2006-08-11 15:15:54.000000', NULL, 1),
(2718104, 375676, 23394, '<td valign="top">nice idea, but the water spray seems to be more of a distraction than anything else.  there''s no context that visually explains it, and, as is, leaves me thinking the image would be better off without it.</td>', 'nice idea, but the water spray seems to be more of a distraction than anything else.  there''s no context that visually explains it, and, as is, leaves me thinking the image would be better off without it.', '2006-08-11 15:16:49.000000', NULL, 1),
(2718107, 375465, 23394, '<td valign="top">ed clarke would kill to get a shot like this.  simple elegance.</td>', 'ed clarke would kill to get a shot like this.  simple elegance.', '2006-08-11 15:17:58.000000', NULL, 1),
(2718109, 372827, 23394, '<td valign="top">nice idea, but too loosely framed to really grab the viewers and keep them.</td>', 'nice idea, but too loosely framed to really grab the viewers and keep them.', '2006-08-11 15:18:44.000000', NULL, 1),
(2718111, 375597, 30049, '<td valign="top">Lensbaby!  Hooray!  They are fun to play with aren''t they?  ;^)  I like your image, it''s an image that will fit well in the family album as well.  The problem here is going to be a couple of things; 1) You''re not really stopping any motion, therefore you haven''t been challenged to control shutter speed like others have.  Voters are going to give you a hit there.  2) Lensbaby lens in general creates many "it''s blurry" comments... ;^)<br/> <br/>Again, nice capture - it''s really a keeper.  Just probably in the wrong challenge.  Good luck.</td>', 'Lensbaby!  Hooray!  They are fun to play with aren''t they?  ;^)  I like your image, it''s an image that will fit well in the family album as well.  The problem here is going to be a couple of things; 1) You''re not really stopping any motion, therefore you haven''t been challenged to control shutter speed like others have.  Voters are going to give you a hit there.  2) Lensbaby lens in general creates many "it''s blurry" comments... ;^) Again, nice capture - it''s really a keeper.  Just probably in the wrong challenge.  Good luck.', '2006-08-11 15:19:18.000000', NULL, 1),
(2718114, 374713, 23394, '<td valign="top">ok, if you look close enough, you can see the boy is off the ground--but only if you look closely enough.  good choice for bw, but not a great choice for showing stopped motion.</td>', 'ok, if you look close enough, you can see the boy is off the ground--but only if you look closely enough.  good choice for bw, but not a great choice for showing stopped motion.', '2006-08-11 15:19:51.000000', NULL, 1),
(2718120, 375820, 23394, '<td valign="top">nice idea, but, if you really want this image to zing, it could use some work.  first, you need to get in position so that the guy in the background isn''t in the background.  next, you caught this just as he was getting ready to start his forward motion.  imagine the shot you would have if you had caught the ball just leaving his fingertips?  lastly, it''s a little soft.  to nail stop motion, you need to be at 1/500 at an absolute minimum.  fast action like this needs at least 1/1000 or faster.</td>', 'nice idea, but, if you really want this image to zing, it could use some work.  first, you need to get in position so that the guy in the background isn''t in the background.  next, you caught this just as he was getting ready to start his forward motion.  imagine the shot you would have if you had caught the ball just leaving his fingertips?  lastly, it''s a little soft.  to nail stop motion, you need to be at 1/500 at an absolute minimum.  fast action like this needs at least 1/1000 or faster.', '2006-08-11 15:22:50.000000', NULL, 1),
(2718121, 375915, 23394, '<td valign="top">nice idea.  bet this took quite a few tries.</td>', 'nice idea.  bet this took quite a few tries.', '2006-08-11 15:23:39.000000', NULL, 1),
(2718124, 374558, 23394, '<td valign="top">yep, you stopped the motion.  the question is, how did you do in appealing to the viewers and voters ;-)</td>', 'yep, you stopped the motion.  the question is, how did you do in appealing to the viewers and voters ;-)', '2006-08-11 15:24:30.000000', NULL, 1),
(2718126, 374640, 23394, '<td valign="top">nice idea, but the bee is going in the wrong direction.  you probably could have framed this up a bit tighter (or cropped it in afterwards).</td>', 'nice idea, but the bee is going in the wrong direction.  you probably could have framed this up a bit tighter (or cropped it in afterwards).', '2006-08-11 15:25:19.000000', NULL, 1),
(2718134, 374302, 23394, '<td valign="top">i get the idea, just wish there was more volume to the water.  as is, it looks like a distracting spray than a full bucket.  on the other hand, i''ve never tried this, so i have no clue how difficult it is...</td>', 'i get the idea, just wish there was more volume to the water.  as is, it looks like a distracting spray than a full bucket.  on the other hand, i''ve never tried this, so i have no clue how difficult it is...', '2006-08-11 15:26:45.000000', NULL, 1),
(2718158, 375213, 30049, '<td valign="top">Nice action shot.  Not quite fast enough on the shutter speed IMO as the water spray coming up behind him isn''t really frozen as the challenge theme requires (no motion blurs, etc...).  The chair in the top left is a bummer as it takes away from the subject.  Nice blue color in the water.  Almost looks like the blue was bumped up some in saturation it''s so vivid.  Just curious, what''s that yellow line in the lower left?  <br/> <br/>Overall, nice capture.  Good luck in the challenge.</td>', 'Nice action shot.  Not quite fast enough on the shutter speed IMO as the water spray coming up behind him isn''t really frozen as the challenge theme requires (no motion blurs, etc...).  The chair in the top left is a bummer as it takes away from the subject.  Nice blue color in the water.  Almost looks like the blue was bumped up some in saturation it''s so vivid.  Just curious, what''s that yellow line in the lower left?   Overall, nice capture.  Good luck in the challenge.', '2006-08-11 15:32:37.000000', NULL, 1),
(2718162, 374975, 30049, '<td valign="top">Yep.  It''s a splash alright.  ;^)  Good color, nice capture of the water splashout.  Lighting looks good as does the focus.  Should do ok with this one.  Good luck.</td>', 'Yep.  It''s a splash alright.  ;^)  Good color, nice capture of the water splashout.  Lighting looks good as does the focus.  Should do ok with this one.  Good luck.', '2006-08-11 15:34:11.000000', NULL, 1),
(2718173, 375087, 30049, '<td valign="top">Cute picture.  You''ve stopped the water spray pretty well.  The boy could be a little sharper (just a tad).  I like the line the grate forms thru your image...that''s cool.  Good luck to you in the challenge.</td>', 'Cute picture.  You''ve stopped the water spray pretty well.  The boy could be a little sharper (just a tad).  I like the line the grate forms thru your image...that''s cool.  Good luck to you in the challenge.', '2006-08-11 15:36:28.000000', NULL, 1),
(2718177, 375840, 30049, '<td valign="top">I like this.  Silhouettes are fun and you''ve done this nicely.  A true silhouette.  There are not any motion blurs/trails so it looks like you did a good job freezing the action to meet the challenge theme of "Stopped Motion".  Overall, very well done.  Good luck in the challenge.</td>', 'I like this.  Silhouettes are fun and you''ve done this nicely.  A true silhouette.  There are not any motion blurs/trails so it looks like you did a good job freezing the action to meet the challenge theme of "Stopped Motion".  Overall, very well done.  Good luck in the challenge.', '2006-08-11 15:37:53.000000', NULL, 1),
(2718202, 375905, 30049, '<td valign="top">This is fun.  Good action shot...everything working for it with one exception and that''s the sky background.  It''s not bad, it''s just not helping you as it could if the detail was brought out via a polarizing filter or post-processing work.  Everything else about this I like.  ;^)  Good luck in the challenge.</td>', 'This is fun.  Good action shot...everything working for it with one exception and that''s the sky background.  It''s not bad, it''s just not helping you as it could if the detail was brought out via a polarizing filter or post-processing work.  Everything else about this I like.  ;^)  Good luck in the challenge.', '2006-08-11 15:44:03.000000', NULL, 1),
(2718206, 375619, 30049, '<td valign="top">This is interesting.  Hard to tell if there''s really any motion being stopped or not with the black background.  In theory, he could be just on his back.  I bring it up not to belittle your image but to make a point on how viewers/voter''s could perceive this.  That''s all.  I like the color tones in this - makes it easy to look at.  Best of luck to you in the challenge.</td>', 'This is interesting.  Hard to tell if there''s really any motion being stopped or not with the black background.  In theory, he could be just on his back.  I bring it up not to belittle your image but to make a point on how viewers/voter''s could perceive this.  That''s all.  I like the color tones in this - makes it easy to look at.  Best of luck to you in the challenge.', '2006-08-11 15:46:07.000000', NULL, 1),
(2718220, 374986, 30049, '<td valign="top">What in the world....?  ;^)  Interesting for sure.  Stopping Action in the water spray I''m taking it?  Wait, I see some mud being splashed...that''s it.  He-he.  The green in the foreground looks a bit muted, like it could use some additional contrast.  While this is fun to look at, it''s almost like you don''t know where to settle in with this image...so many different subjects to take in.  JMO of course.  Good luck in the challenge.</td>', 'What in the world....?  ;^)  Interesting for sure.  Stopping Action in the water spray I''m taking it?  Wait, I see some mud being splashed...that''s it.  He-he.  The green in the foreground looks a bit muted, like it could use some additional contrast.  While this is fun to look at, it''s almost like you don''t know where to settle in with this image...so many different subjects to take in.  JMO of course.  Good luck in the challenge.', '2006-08-11 15:49:04.000000', NULL, 1),
(2718224, 375913, 30049, '<td valign="top">Yikes!  Took me a sec to see the skates!  This is clean, interesting, well lit and focused.  Should do ok with this entry.  Almost looks like the person flipping is on the spiked wall.  Best of luck in the challenge.</td>', 'Yikes!  Took me a sec to see the skates!  This is clean, interesting, well lit and focused.  Should do ok with this entry.  Almost looks like the person flipping is on the spiked wall.  Best of luck in the challenge.', '2006-08-11 15:50:57.000000', NULL, 1),
(2718228, 372964, 30049, '<td valign="top">This is unique.  Good for you.  Makes the viewer think a little, which is fine overall.  Hopefully the voters will slow down enough to figure it out.  ;^)  Only distraction for me is the few branches in the top left.  Why not clone those out since it''s advanced editing?  Just a thought.  Best of luck to you in the challenge.</td>', 'This is unique.  Good for you.  Makes the viewer think a little, which is fine overall.  Hopefully the voters will slow down enough to figure it out.  ;^)  Only distraction for me is the few branches in the top left.  Why not clone those out since it''s advanced editing?  Just a thought.  Best of luck to you in the challenge.', '2006-08-11 15:52:50.000000', NULL, 1),
(2718230, 375545, 23394, '<td valign="top">nice idea, but a bit soft and loose.  if you were in tight on their faces, you would have had a killer shot.</td>', 'nice idea, but a bit soft and loose.  if you were in tight on their faces, you would have had a killer shot.', '2006-08-11 15:53:53.000000', NULL, 1),
(2718231, 375091, 30049, '<td valign="top">Not sure that the rotation helps the impact on this.  Haven''t quite stopped the motion as the hammer is a little blurry and many of the pieces flying around are OOF.  Great effort, and I''m sure you had fun putting this together.  Good luck in the challenge.</td>', 'Not sure that the rotation helps the impact on this.  Haven''t quite stopped the motion as the hammer is a little blurry and many of the pieces flying around are OOF.  Great effort, and I''m sure you had fun putting this together.  Good luck in the challenge.', '2006-08-11 15:54:29.000000', NULL, 1),
(2718233, 375827, 30049, '<td valign="top">Crisp, sharp, good color.  Stopped the motion just fine.  Nicely done.  See you in the top 20 with this one...  ;^)  Good luck.</td>', 'Crisp, sharp, good color.  Stopped the motion just fine.  Nicely done.  See you in the top 20 with this one...  ;^)  Good luck.', '2006-08-11 15:55:32.000000', NULL, 1),
(2718235, 375623, 30049, '<td valign="top">Interesting subject, fun image to look at.  Motion is stopped pretty well.  One suggestion from me is to give this a small shot of contrast and maybe bump the color saturation a notch or two.  Darn utility pole anyway!  ;^)  Good luck in the challenge.</td>', 'Interesting subject, fun image to look at.  Motion is stopped pretty well.  One suggestion from me is to give this a small shot of contrast and maybe bump the color saturation a notch or two.  Darn utility pole anyway!  ;^)  Good luck in the challenge.', '2006-08-11 15:56:58.000000', NULL, 1),
(2718236, 374205, 23394, '<td valign="top">nice idea, but too soft and a bit too over-exposed.  this is a tough shot to meter and shoot--there are just so many things making it difficult.  if you had found a different perspective where you could have zeroed in on one or two people''s faces and caught their expressions amidst the spray.</td>', 'nice idea, but too soft and a bit too over-exposed.  this is a tough shot to meter and shoot--there are just so many things making it difficult.  if you had found a different perspective where you could have zeroed in on one or two people''s faces and caught their expressions amidst the spray.', '2006-08-11 15:57:21.000000', NULL, 1),
(2718238, 375647, 30049, '<td valign="top">Ahhh.  Nice setup. ;^)  A little noise in the image and I think your B/W points are off a bit.  Is the right tilt intentional?  Good luck in the challenge.</td>', 'Ahhh.  Nice setup. ;^)  A little noise in the image and I think your B/W points are off a bit.  Is the right tilt intentional?  Good luck in the challenge.', '2006-08-11 15:58:27.000000', NULL, 1),
(2718239, 375309, 23394, '<td valign="top">nice work!  this is so much better than the standard fare than comes from opportunities such as this.  i think it deserves a bump.</td>', 'nice work!  this is so much better than the standard fare than comes from opportunities such as this.  i think it deserves a bump.', '2006-08-11 15:58:28.000000', NULL, 1),
(2718244, 375209, 23394, '<td valign="top">nice idea, cool lighting and colors.  it could stand to be a bit sharper.  for stuff like this (stop motion), you''re gonna want to be close to 1/1000 to really nail it.  with that much light, you could bump your iso without losing detail to noise.</td>', 'nice idea, cool lighting and colors.  it could stand to be a bit sharper.  for stuff like this (stop motion), you''re gonna want to be close to 1/1000 to really nail it.  with that much light, you could bump your iso without losing detail to noise.', '2006-08-11 16:00:02.000000', NULL, 1),
(2718245, 375911, 30049, '<td valign="top">Good color.  Nice stopped motion.   Composition works and the exposure and focus are right on the mark.  Should do ok with this one.  Only thing that might help move this up is to have something for the girl to play with, shovel, etc...  Overall, nicely done.  Best of luck in the challenge.</td>', 'Good color.  Nice stopped motion.   Composition works and the exposure and focus are right on the mark.  Should do ok with this one.  Only thing that might help move this up is to have something for the girl to play with, shovel, etc...  Overall, nicely done.  Best of luck in the challenge.', '2006-08-11 16:00:10.000000', NULL, 1),
(2718248, 374985, 23394, '<td valign="top">yes, you stopped the water, but the end result doesn''t really do much other than sit there.  i''m not quite sure what you could have done differently, but as is, it''s just not that interesting.</td>', 'yes, you stopped the water, but the end result doesn''t really do much other than sit there.  i''m not quite sure what you could have done differently, but as is, it''s just not that interesting.', '2006-08-11 16:01:31.000000', NULL, 1),
(2718250, 373328, 23394, '<td valign="top">nice capture.  if you get a chance, try shooting from below, up into their faces.  they can get some pretty intense expressions.</td>', 'nice capture.  if you get a chance, try shooting from below, up into their faces.  they can get some pretty intense expressions.', '2006-08-11 16:02:53.000000', NULL, 1),
(2718251, 375915, 30049, '<td valign="top">This is fun.  Color is mostly natural I''d imagine with that backlit sun.  Motion is stopped ok.  For some reason it seems a little soft.  Could be the impression the viewer gets from the leading rope which is a little blurry from aperture DOF.  The actual spray around the skier is pretty sharp.  Good luck.</td>', 'This is fun.  Color is mostly natural I''d imagine with that backlit sun.  Motion is stopped ok.  For some reason it seems a little soft.  Could be the impression the viewer gets from the leading rope which is a little blurry from aperture DOF.  The actual spray around the skier is pretty sharp.  Good luck.', '2006-08-11 16:03:14.000000', NULL, 1),
(2718252, 375907, 61313, '<td valign="top">Where in the world did you come across the ferromagnetic material... I love this stuff, great idea.</td>', 'Where in the world did you come across the ferromagnetic material... I love this stuff, great idea.', '2006-08-11 16:03:17.000000', NULL, 1),
(2718257, 375890, 23394, '<td valign="top">i get the idea, and yes, you stopped the motion, but your subject looks more like you made her do it than if she was doing it out of sheer joy.  also, this is shot pretty much as a dead-on documentary snapshot.  try using different angles to produce different dynamics in order to make your images more appealing.</td>', 'i get the idea, and yes, you stopped the motion, but your subject looks more like you made her do it than if she was doing it out of sheer joy.  also, this is shot pretty much as a dead-on documentary snapshot.  try using different angles to produce different dynamics in order to make your images more appealing.', '2006-08-11 16:04:33.000000', NULL, 1),
(2718260, 374375, 30049, '<td valign="top">Ok.  Here''s a splash that''s going places!  ;^)  Sorry, I''ve seen so many in this challenge I''m getting tired of seeing water.  As cliche as this shot is, it''s going to make the front page.  It''s clean, crisp, well lit and focused.  Congratulations in advance on your ribbon.  ;^)  Take care.</td>', 'Ok.  Here''s a splash that''s going places!  ;^)  Sorry, I''ve seen so many in this challenge I''m getting tired of seeing water.  As cliche as this shot is, it''s going to make the front page.  It''s clean, crisp, well lit and focused.  Congratulations in advance on your ribbon.  ;^)  Take care.', '2006-08-11 16:05:25.000000', NULL, 1),
