(2720965, 375647, 29770, '<td valign="top">Nice concept and good capture.  My only complaint is the color balance.  The whole image looks a little blue cast to me.  Otherwise, I give it a 6.</td>', 'Nice concept and good capture.  My only complaint is the color balance.  The whole image looks a little blue cast to me.  Otherwise, I give it a 6.', '2006-08-12 17:23:00.000000', NULL, 1),
(2720967, 375252, 29770, '<td valign="top">Nice job capturing the pitch coming in and the batter swinging.  I like it.</td>', 'Nice job capturing the pitch coming in and the batter swinging.  I like it.', '2006-08-12 17:24:10.000000', NULL, 1),
(2720968, 375894, 29770, '<td valign="top">I like the motion in this image.  The colors are good too.</td>', 'I like the motion in this image.  The colors are good too.', '2006-08-12 17:24:50.000000', NULL, 1),
