(2721627, 375514, 29011, '<td valign="top">Wonderful! Very much like the idea of using a blue lightbulb on white background, not just white bulb on black. Works great for the contrast and makes it more interesting. Like the blue shadows on the surface.</td>', 'Wonderful! Very much like the idea of using a blue lightbulb on white background, not just white bulb on black. Works great for the contrast and makes it more interesting. Like the blue shadows on the surface.', '2006-08-13 00:25:37.000000', NULL, 1),
(2721637, 375791, 29011, '<td valign="top">What a great idea. One of the funnest shots of the challenge. Only nitpick is the popcorn seems to be overexposed, and the hotspot on the lady''s forehead.</td>', 'What a great idea. One of the funnest shots of the challenge. Only nitpick is the popcorn seems to be overexposed, and the hotspot on the lady''s forehead.', '2006-08-13 00:29:30.000000', NULL, 1),
