(2723062, 375648, 63947, '<td valign="top">Nice use of long exposure.</td>', 'Nice use of long exposure.', '2006-08-13 18:55:43.000000', NULL, 1),
(2723064, 375414, 63947, '<td valign="top">Very busy.  Lots going on.  Some of it good, some of it distracting.</td>', 'Very busy.  Lots going on.  Some of it good, some of it distracting.', '2006-08-13 18:56:55.000000', NULL, 1),
(2723067, 374738, 63947, '<td valign="top">You really get a sense of weight in this picture.</td>', 'You really get a sense of weight in this picture.', '2006-08-13 18:57:52.000000', NULL, 1),
(2723069, 374229, 63947, '<td valign="top">I don''t like the cropping in this one.  It makes the picture seem incompleete somehow.</td>', 'I don''t like the cropping in this one.  It makes the picture seem incompleete somehow.', '2006-08-13 18:58:47.000000', NULL, 1),
(2723070, 375416, 63947, '<td valign="top">I like the framing, but the colors seem a little muted and you expect vibrancy from this kind of scene.</td>', 'I like the framing, but the colors seem a little muted and you expect vibrancy from this kind of scene.', '2006-08-13 18:59:30.000000', NULL, 1),
(2723076, 374999, 63947, '<td valign="top">Wow!  Way to track that motion!  Just wish the colors weren''t so blue.  This action feels hot but the colors say cold.</td>', 'Wow!  Way to track that motion!  Just wish the colors weren''t so blue.  This action feels hot but the colors say cold.', '2006-08-13 19:00:58.000000', NULL, 1),
(2723081, 374344, 63947, '<td valign="top">Love the colorized effect.  Takes an otherwise ordinary setting and gives it flair.</td>', 'Love the colorized effect.  Takes an otherwise ordinary setting and gives it flair.', '2006-08-13 19:02:25.000000', NULL, 1),
(2723085, 374058, 63947, '<td valign="top">If you would''ve used a martini glass and an olive you could sell this to any Vodka manufacturer.  I don''t get the quarter in the water though.  What''s the meaning?</td>', 'If you would''ve used a martini glass and an olive you could sell this to any Vodka manufacturer.  I don''t get the quarter in the water though.  What''s the meaning?', '2006-08-13 19:03:44.000000', NULL, 1),
(2723088, 375678, 63947, '<td valign="top">I really dig this picture.</td>', 'I really dig this picture.', '2006-08-13 19:04:17.000000', NULL, 1),
(2723093, 375875, 63947, '<td valign="top">I like the color, light, and composition.  Great photo!</td>', 'I like the color, light, and composition.  Great photo!', '2006-08-13 19:05:34.000000', NULL, 1),
(2723094, 374922, 63947, '<td valign="top">Nice exposure and color.</td>', 'Nice exposure and color.', '2006-08-13 19:06:51.000000', NULL, 1),
(2723097, 375366, 63947, '<td valign="top">I really like the colors in this picture.</td>', 'I really like the colors in this picture.', '2006-08-13 19:07:40.000000', NULL, 1),
(2723102, 375809, 63947, '<td valign="top">Awwe!  Poor fish!  But cool framing and color.</td>', 'Awwe!  Poor fish!  But cool framing and color.', '2006-08-13 19:09:08.000000', NULL, 1),
(2723105, 375278, 63947, '<td valign="top">Colors and positioning of objects is really nice</td>', 'Colors and positioning of objects is really nice', '2006-08-13 19:10:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2723107, 375656, 63947, '<td valign="top">Awesome picture</td>', 'Awesome picture', '2006-08-13 19:11:38.000000', NULL, 1),
(2723109, 375637, 63947, '<td valign="top">Seems to lack clarity.  Don''t like the cool, muted colors.</td>', 'Seems to lack clarity.  Don''t like the cool, muted colors.', '2006-08-13 19:12:33.000000', NULL, 1),
(2723110, 374558, 63947, '<td valign="top">Feels entirely too staged.</td>', 'Feels entirely too staged.', '2006-08-13 19:12:56.000000', NULL, 1),
(2723119, 375586, 63947, '<td valign="top">Feels warm and fuzzy.  I like it.</td>', 'Feels warm and fuzzy.  I like it.', '2006-08-13 19:14:30.000000', NULL, 1),
(2723121, 375091, 63947, '<td valign="top">Love the vibrant colors... really draws the eye.</td>', 'Love the vibrant colors... really draws the eye.', '2006-08-13 19:15:12.000000', NULL, 1),
(2723126, 375873, 63947, '<td valign="top">Looks too plastic.</td>', 'Looks too plastic.', '2006-08-13 19:18:54.000000', NULL, 1),
(2723127, 375904, 63947, '<td valign="top">really neat.</td>', 'really neat.', '2006-08-13 19:19:47.000000', NULL, 1),
(2723134, 375726, 63947, '<td valign="top">Wow!  Such color!</td>', 'Wow!  Such color!', '2006-08-13 19:22:23.000000', NULL, 1),
(2723135, 375580, 63953, '<td valign="top">What is not to like about this photograph.  It captures motion, form, and balance with tremendous grace.  The symmetry of the hair and the water is incredible.  Wonderful shot!</td>', 'What is not to like about this photograph.  It captures motion, form, and balance with tremendous grace.  The symmetry of the hair and the water is incredible.  Wonderful shot!', '2006-08-13 19:23:13.000000', NULL, 1),
(2723137, 374700, 63947, '<td valign="top">Nice pic, but I just don''t get it.</td>', 'Nice pic, but I just don''t get it.', '2006-08-13 19:23:50.000000', NULL, 1),
(2723140, 375257, 63947, '<td valign="top">You would''ve pegged this for me if you would''ve used clean hands.</td>', 'You would''ve pegged this for me if you would''ve used clean hands.', '2006-08-13 19:27:11.000000', NULL, 1),
(2723141, 375435, 63947, '<td valign="top">Love it!</td>', 'Love it!', '2006-08-13 19:27:26.000000', NULL, 1),
(2723201, 375703, 8610, '<td valign="top">Íslensk flúvéll... vei!!!</td>', 'Íslensk flúvéll... vei!!!', '2006-08-13 19:49:46.000000', NULL, 1),
(2723253, 374558, 3032, '<td valign="top">Reminds of Fight Club / Snatch. Cool shot.</td>', 'Reminds of Fight Club / Snatch. Cool shot.', '2006-08-13 20:26:23.000000', NULL, 1),
(2723271, 375773, 63955, '<td valign="top">Great capture, the water is still in the ballon shape</td>', 'Great capture, the water is still in the ballon shape', '2006-08-13 20:35:39.000000', NULL, 1),
(2723288, 375623, 40370, '<td valign="top">Shame about the telephone pole.</td>', 'Shame about the telephone pole.', '2006-08-13 20:43:46.000000', NULL, 1),
(2723297, 373328, 60195, '<td valign="top">Great capture!  Excellent timing, and nice job on freezing the action :O)</td>', 'Great capture!  Excellent timing, and nice job on freezing the action :O)', '2006-08-13 20:46:07.000000', NULL, 1),
(2723298, 374870, 40370, '<td valign="top">Cool, I''d have gotten the red thing out of the frame though.</td>', 'Cool, I''d have gotten the red thing out of the frame though.', '2006-08-13 20:46:13.000000', NULL, 1),
(2723311, 375645, 40370, '<td valign="top">Looks like this navel burped fire. The sunset placement is just too weird.</td>', 'Looks like this navel burped fire. The sunset placement is just too weird.', '2006-08-13 20:50:50.000000', NULL, 1),
(2723339, 375819, 40370, '<td valign="top">He looks apprehensive, is that the ride that drops you into a freefall? Scary. I am sure this would be a tough one to shoot, but looks like the shutter wasn''t fast enough to get complete focus.</td>', 'He looks apprehensive, is that the ride that drops you into a freefall? Scary. I am sure this would be a tough one to shoot, but looks like the shutter wasn''t fast enough to get complete focus.', '2006-08-13 21:08:29.000000', NULL, 1),
(2723346, 375809, 40370, '<td valign="top">Amazing ... how many times has that word been posted to your entry??</td>', 'Amazing ... how many times has that word been posted to your entry??', '2006-08-13 21:10:11.000000', NULL, 1),
(2723358, 375803, 40370, '<td valign="top">Excellent capture of the ball, colors are real. I would have cropped out the left two dudes, for less distraction from the action.</td>', 'Excellent capture of the ball, colors are real. I would have cropped out the left two dudes, for less distraction from the action.', '2006-08-13 21:17:45.000000', NULL, 1),
(2723362, 375726, 40370, '<td valign="top">The border is distracting in this instance, and the hot-spots are prominent. But the green color is intense and the stop motion is definitely there.</td>', 'The border is distracting in this instance, and the hot-spots are prominent. But the green color is intense and the stop motion is definitely there.', '2006-08-13 21:19:33.000000', NULL, 1),
(2723377, 375435, 40370, '<td valign="top">A tad sharp but majestic animals like this always merit the extra point, and you definitely stopped some motion.</td>', 'A tad sharp but majestic animals like this always merit the extra point, and you definitely stopped some motion.', '2006-08-13 21:29:08.000000', NULL, 1),
(2723378, 375796, 46330, '<td valign="top">Great capture.  You might want to bump the contrast slightly with curves or levels to give a true black to add a bit more punch.</td>', 'Great capture.  You might want to bump the contrast slightly with curves or levels to give a true black to add a bit more punch.', '2006-08-13 21:30:01.000000', NULL, 1),
(2723379, 375580, 40370, '<td valign="top">Not original, but definitely done well, one of the best of it''s kind.</td>', 'Not original, but definitely done well, one of the best of it''s kind.', '2006-08-13 21:30:05.000000', NULL, 1),
(2723400, 375260, 40370, '<td valign="top">Very cool capture that invokes a few drunken memories. I have no idea how you achieved this amazing image. Lite-beer no doubt, where''s the bubbles?</td>', 'Very cool capture that invokes a few drunken memories. I have no idea how you achieved this amazing image. Lite-beer no doubt, where''s the bubbles?', '2006-08-13 21:43:01.000000', NULL, 1),
(2723406, 375859, 40370, '<td valign="top">This image is distinctive because his legs are tucked up under him showing flight. Good work. Watch the tilt/crop next time to avoid the white corner.</td>', 'This image is distinctive because his legs are tucked up under him showing flight. Good work. Watch the tilt/crop next time to avoid the white corner.', '2006-08-13 21:47:04.000000', NULL, 1),
(2723416, 375573, 40370, '<td valign="top">Although they add a nice backdrop, your subject is a little overwhelmed by the sunset and clouds. Good athletic position to represent "stopped motion", wish his lower foot was off the ground a bit more to avoid being swallowed up in the dark horizon line.</td>', 'Although they add a nice backdrop, your subject is a little overwhelmed by the sunset and clouds. Good athletic position to represent "stopped motion", wish his lower foot was off the ground a bit more to avoid being swallowed up in the dark horizon line.', '2006-08-13 21:51:57.000000', NULL, 1),
(2723425, 375591, 40370, '<td valign="top">Love the posture ... one foot pointed, the other flexed, arms flying.<br/>I really like this image, the grayscale is nice but I wonder how the natural color would look. Lastly, I would like to see a bit more "sea" in the foreground, it seems it would balance the massive rock within the frame.</td>', 'Love the posture ... one foot pointed, the other flexed, arms flying.I really like this image, the grayscale is nice but I wonder how the natural color would look. Lastly, I would like to see a bit more "sea" in the foreground, it seems it would balance the massive rock within the frame.', '2006-08-13 21:57:50.000000', NULL, 1),
(2723430, 374986, 40370, '<td valign="top">Wholly cow ... there should be a "dirty" challenge, for this would win. (DrJones aside).</td>', 'Wholly cow ... there should be a "dirty" challenge, for this would win. (DrJones aside).', '2006-08-13 22:01:52.000000', NULL, 1),
(2723435, 375746, 40370, '<td valign="top">Okay, the horizontal presentation is a bit creepy, the feline looks as if he/she just croaked. No matter what angle I can imagine, this picture is too strange to recognize the goal ... stopped motion.</td>', 'Okay, the horizontal presentation is a bit creepy, the feline looks as if he/she just croaked. No matter what angle I can imagine, this picture is too strange to recognize the goal ... stopped motion.', '2006-08-13 22:05:37.000000', NULL, 1),
(2723449, 375916, 40370, '<td valign="top">I love the idea and the long horizontal line-up is great. Would like to see more foreground as the image seems tightly cropped both top and bottom. Also, straightening the number banner would be beneficial.</td>', 'I love the idea and the long horizontal line-up is great. Would like to see more foreground as the image seems tightly cropped both top and bottom. Also, straightening the number banner would be beneficial.', '2006-08-13 22:14:38.000000', NULL, 1),
(2723454, 375853, 40370, '<td valign="top">Clear &amp; Concise ... like a good image accompanying the news story. Love the contrast of sand to sky.</td>', 'Clear & Concise ... like a good image accompanying the news story. Love the contrast of sand to sky.', '2006-08-13 22:16:56.000000', NULL, 1),
(2723458, 374422, 40370, '<td valign="top">What fun colors found in the sky.</td>', 'What fun colors found in the sky.', '2006-08-13 22:18:19.000000', NULL, 1),
(2723466, 375778, 40370, '<td valign="top">One of the best insect images in this challenge. The bee just pops out at the viewer, and the purple flowers are a great compliment. I''d like to see the bee up closer, maybe cropped the right and top just a bit as not to change the nice lines of the flowers too much.</td>', 'One of the best insect images in this challenge. The bee just pops out at the viewer, and the purple flowers are a great compliment. I''d like to see the bee up closer, maybe cropped the right and top just a bit as not to change the nice lines of the flowers too much.', '2006-08-13 22:22:06.000000', NULL, 1),
(2723469, 375610, 40370, '<td valign="top">Ahhh ... somethin'' diff-rnt.</td>', 'Ahhh ... somethin'' diff-rnt.', '2006-08-13 22:22:58.000000', NULL, 1),
(2723483, 374375, 40370, '<td valign="top">Very calculated, right down to the shadows, exceptional work. This motion is so crisp and the water is frigidly colorless rendering the green subject so intense.</td>', 'Very calculated, right down to the shadows, exceptional work. This motion is so crisp and the water is frigidly colorless rendering the green subject so intense.', '2006-08-13 22:30:22.000000', NULL, 1),
(2723487, 375754, 40370, '<td valign="top">So the spectators look real, why does the subject look like pixelated plastic? Low lighting really took it''s toll with this image. Or poor post-processing?</td>', 'So the spectators look real, why does the subject look like pixelated plastic? Low lighting really took it''s toll with this image. Or poor post-processing?', '2006-08-13 22:32:46.000000', NULL, 1),
(2723489, 375826, 40370, '<td valign="top">Is that in-bound or out-bound? No matter, good capture.</td>', 'Is that in-bound or out-bound? No matter, good capture.', '2006-08-13 22:33:28.000000', NULL, 1),
(2723492, 375648, 40370, '<td valign="top">A different take on the challenge, the sepia works well to set the reverent tone.</td>', 'A different take on the challenge, the sepia works well to set the reverent tone.', '2006-08-13 22:35:13.000000', NULL, 1),
(2723493, 374302, 40370, '<td valign="top">Say it ... don''t spray it.</td>', 'Say it ... don''t spray it.', '2006-08-13 22:35:44.000000', NULL, 1),
(2723495, 375771, 40370, '<td valign="top">Not my interpretation of the challenge, but too cool to vote down. I hope others give you the benefit of the doubt.</td>', 'Not my interpretation of the challenge, but too cool to vote down. I hope others give you the benefit of the doubt.', '2006-08-13 22:38:12.000000', NULL, 1),
(2723496, 375788, 40370, '<td valign="top">Good job with classic expressions.</td>', 'Good job with classic expressions.', '2006-08-13 22:39:00.000000', NULL, 1),
(2723499, 374934, 40370, '<td valign="top">Wow, it''s like you said "say mouse" and he looked and smiled for the camera. Definitely one of the better bird images in this challenge.</td>', 'Wow, it''s like you said "say mouse" and he looked and smiled for the camera. Definitely one of the better bird images in this challenge.', '2006-08-13 22:40:32.000000', NULL, 1),
(2723509, 375656, 40370, '<td valign="top">Audobon Society''s next cover. Very dream-like in the softening of the wings, and composition is fine.</td>', 'Audobon Society''s next cover. Very dream-like in the softening of the wings, and composition is fine.', '2006-08-13 22:45:08.000000', NULL, 1),
(2723519, 375249, 40370, '<td valign="top">Captivating image, I love the inclusion of three birds, the distance renders the feeder a better accent to the image than some of the other entrant''s close-up shots. Simply amazing.</td>', 'Captivating image, I love the inclusion of three birds, the distance renders the feeder a better accent to the image than some of the other entrant''s close-up shots. Simply amazing.', '2006-08-13 22:50:14.000000', NULL, 1),
(2723525, 375816, 40370, '<td valign="top">Border is a bit thick, but the post-processing renders this image interesting, the net is especially compelling.</td>', 'Border is a bit thick, but the post-processing renders this image interesting, the net is especially compelling.', '2006-08-13 22:52:23.000000', NULL, 1),
(2723538, 375311, 40370, '<td valign="top">I think the coloring you''ve chosen is appropriate for this image, kind of gritty similar to the sport. I wish we were up a little closer to the action though.</td>', 'I think the coloring you''ve chosen is appropriate for this image, kind of gritty similar to the sport. I wish we were up a little closer to the action though.', '2006-08-13 22:56:02.000000', NULL, 1),
(2723543, 375620, 40370, '<td valign="top">Definitely action, I like the foot that is clearly off the board. Unfortunately, the shadow is a distraction for me, in fact I''d love to see this shot in daylight with blue sky rather than black night.</td>', 'Definitely action, I like the foot that is clearly off the board. Unfortunately, the shadow is a distraction for me, in fact I''d love to see this shot in daylight with blue sky rather than black night.', '2006-08-13 22:59:29.000000', NULL, 1),
(2723548, 375863, 40370, '<td valign="top">Sweet, nice splash. The legs (human that is) are a nice accent to the canine. Good sand/water mix.</td>', 'Sweet, nice splash. The legs (human that is) are a nice accent to the canine. Good sand/water mix.', '2006-08-13 23:01:21.000000', NULL, 1),
(2723554, 375889, 40370, '<td valign="top">Splash is awesome, composition is good, color ... I''ve been warned that milk products show up yellowish, I''d like to see this with the yellow desaturated a bit.</td>', 'Splash is awesome, composition is good, color ... I''ve been warned that milk products show up yellowish, I''d like to see this with the yellow desaturated a bit.', '2006-08-13 23:04:07.000000', NULL, 1),
(2723569, 375688, 40370, '<td valign="top">I want dessert now. I love everything about this except the gray/blue color around the edge of the dish, I know ... picky, picky. Excellent clarity on the fruit.</td>', 'I want dessert now. I love everything about this except the gray/blue color around the edge of the dish, I know ... picky, picky. Excellent clarity on the fruit.', '2006-08-13 23:07:41.000000', NULL, 1),
(2723575, 375689, 40370, '<td valign="top">That''s wild.</td>', 'That''s wild.', '2006-08-13 23:10:48.000000', NULL, 1),
(2723579, 375809, 7910, '<td valign="top">Superb!</td>', 'Superb!', '2006-08-13 23:13:07.000000', NULL, 1),
(2723584, 375909, 40370, '<td valign="top">The view of under the board makes this top-notch. Clarity is perfect. I like the composition fine for this challenge but I''d love to see this image with the full sail just for fun.</td>', 'The view of under the board makes this top-notch. Clarity is perfect. I like the composition fine for this challenge but I''d love to see this image with the full sail just for fun.', '2006-08-13 23:14:28.000000', NULL, 1),
(2723605, 374975, 40370, '<td valign="top">Wow ... that''s some clear water, filtered in the way only mountain springs can do. The blue tones and the intense red of the strawberry are outstanding. The "stop" is flawless. Upon first glance though, my thought was this image needed to be tilted 1 degree CW for absolute perfection.</td>', 'Wow ... that''s some clear water, filtered in the way only mountain springs can do. The blue tones and the intense red of the strawberry are outstanding. The "stop" is flawless. Upon first glance though, my thought was this image needed to be tilted 1 degree CW for absolute perfection.', '2006-08-13 23:20:32.000000', NULL, 1),
(2723617, 375835, 40370, '<td valign="top">Most precise feather image of the hummingbird entries. Wow.</td>', 'Most precise feather image of the hummingbird entries. Wow.', '2006-08-13 23:24:02.000000', NULL, 1),
(2723618, 374344, 19023, '<td valign="top">good colors! I like.</td>', 'good colors! I like.', '2006-08-13 23:24:12.000000', NULL, 1),
(2723639, 375906, 40370, '<td valign="top">The inclusion of the laid-back pier sets this image apart from some of the other ordinary bird entries.</td>', 'The inclusion of the laid-back pier sets this image apart from some of the other ordinary bird entries.', '2006-08-13 23:30:13.000000', NULL, 1),
(2723651, 375873, 40370, '<td valign="top">Imagination gone wild!! Brainpower to execute ... still in place. <br/>Only in my dreams could I think of a way to improve this fantasy.</td>', 'Imagination gone wild!! Brainpower to execute ... still in place. Only in my dreams could I think of a way to improve this fantasy.', '2006-08-13 23:35:02.000000', NULL, 1),
(2723665, 374558, 40370, '<td valign="top">Flashback ... violence shouldn''t be so blossoming. But it is, you''ve achieved a realistic look into a world nobody  truly belongs to.</td>', 'Flashback ... violence shouldn''t be so blossoming. But it is, you''ve achieved a realistic look into a world nobody  truly belongs to.', '2006-08-13 23:40:02.000000', NULL, 1),
(2723671, 375422, 40370, '<td valign="top">Love the composition of the three, each providing a different character to the image, the backdrop is interesting yet not too distracting. I only wish the ultimate focus was on the foreground boarder as he is your action.</td>', 'Love the composition of the three, each providing a different character to the image, the backdrop is interesting yet not too distracting. I only wish the ultimate focus was on the foreground boarder as he is your action.', '2006-08-13 23:43:12.000000', NULL, 1),
(2723674, 375614, 40370, '<td valign="top">Details ... details, de-tongue is purr-fect.</td>', 'Details ... details, de-tongue is purr-fect.', '2006-08-13 23:44:19.000000', NULL, 1),
(2723679, 375586, 40370, '<td valign="top">Love the chosen DOF in this colorful image.</td>', 'Love the chosen DOF in this colorful image.', '2006-08-13 23:45:11.000000', NULL, 1),
(2723686, 375655, 40370, '<td valign="top">Wow, what delightful color in his costume.</td>', 'Wow, what delightful color in his costume.', '2006-08-13 23:48:01.000000', NULL, 1),
(2723689, 375614, 53147, '<td valign="top">I am a sucker for a great cat shot. Bumping up a couple.</td>', 'I am a sucker for a great cat shot. Bumping up a couple.', '2006-08-13 23:48:29.000000', NULL, 1),
(2723693, 375809, 53147, '<td valign="top">Cool creative shot. Looking forward to seeing how this was done. One of my two top rated picks for this challenge. Giving you an 8 right now - but I expect to be back later.<br/> <br/>Back again - bumping up. This is my top choice for the challenge. Graet job.</td>', 'Cool creative shot. Looking forward to seeing how this was done. One of my two top rated picks for this challenge. Giving you an 8 right now - but I expect to be back later. Back again - bumping up. This is my top choice for the challenge. Graet job.', '2006-08-13 23:49:19.000000', NULL, 1),
(2723700, 374169, 40370, '<td valign="top">I love the shadows and flair of the hair, more compelling as "stop motion" than the airborne skateboard ... 2 for 1. Good.</td>', 'I love the shadows and flair of the hair, more compelling as "stop motion" than the airborne skateboard ... 2 for 1. Good.', '2006-08-13 23:51:49.000000', NULL, 1),
(2723706, 375465, 40370, '<td valign="top">Chic ... the subdued tones are wonderful in this airborne rush.</td>', 'Chic ... the subdued tones are wonderful in this airborne rush.', '2006-08-13 23:55:49.000000', NULL, 1),
(2723716, 375913, 40370, '<td valign="top">How ''bout sleeping on a "bed of nails"? Cool shot, I actually like the spectator element also.</td>', 'How ''bout sleeping on a "bed of nails"? Cool shot, I actually like the spectator element also.', '2006-08-13 23:59:42.000000', NULL, 1),
(2723728, 375435, 39664, '<td valign="top">Very nice!!!  Amazing capture....this is a 10 for sure!</td>', 'Very nice!!!  Amazing capture....this is a 10 for sure!', '2006-08-14 00:05:01.000000', NULL, 1),
(2723730, 375881, 40370, '<td valign="top">Dynamic in-flight shot, the downward dive is classic, and the duo-tone does justice to this bird of prey.</td>', 'Dynamic in-flight shot, the downward dive is classic, and the duo-tone does justice to this bird of prey.', '2006-08-14 00:05:34.000000', NULL, 1),
(2723736, 375710, 39664, '<td valign="top">Buono da mangiare!</td>', 'Buono da mangiare!', '2006-08-14 00:10:08.000000', NULL, 1),
